contracts/main/strategy/hub/HubStrategyK.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {IStrategy, IStrategyDustReceiver} from "../../../interfaces/core/IStrategy.sol";
import {IStrategyManager} from "../../../interfaces/core/IStrategyManager.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {IEventEmitter} from "../../../interfaces/core/IEventEmitter.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {FunctionParameters} from "../../../library/core/FunctionParameters.sol";
import {IPriceOracle} from "../../../interfaces/core/IPriceOracle.sol";
import {ErrorLibrary} from "../../../library/core/ErrorLibrary.sol";
import {IProtocolRegistry} from "../../../interfaces/core/IProtocolRegistry.sol";
import {IKodiakIsland} from "../../../interfaces/strategy/IKodiakIsland.sol";
import {IIslandRouter} from "../../../interfaces/strategy/IIslandRouter.sol";
import {IKodiakSwapController} from "../../../interfaces/strategy/IKodiakSwapController.sol";
import {IBGTGauge} from "../../../interfaces/external/bera/IBGTGauge.sol";
import {IERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import {SafeERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import {IRewardsDistributor} from "../../../interfaces/core/IRewardsDistributor.sol";
import {StrategyLibrary} from "../../../library/strategy/StrategyLibrary.sol";

contract HubStrategyKodiakIsland is
    Initializable,
    ReentrancyGuardUpgradeable,
    IStrategy,
    UUPSUpgradeable,
    OwnableUpgradeable
{
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    using SafeERC20Upgradeable for IERC20Upgradeable;

    address public constant WBERA = 0x6969696969696969696969696969696969696969;

    /********************/
    /* Constants */
    /********************/
    uint256 public constant MAX_SLIPPAGE = 10000; // 100% in basis points
    IProtocolRegistry public protocolRegistry;
    uint256 public fee; // fee tier for reward token swaps (e.g. iBGT/HONEY)
    address public baseToken;
    address public kodiakSwapRouter;
    address public islandRouter;
    IKodiakIsland public island;
    IBGTGauge public hubVault;
    address public strategyManager;

    /********************/
    /* Reward-swap routing (appended for upgrade — keep at the end of storage) */
    /********************/
    // When `rewardIntermediaryToken` is set, getReward swaps each reward token to baseToken
    // through this intermediary (e.g. iBGT -> WBERA -> HONEY) because no liquid direct pool
    // exists. When unset (address(0)), getReward falls back to the direct single-hop swap.
    address public rewardIntermediaryToken;
    uint24 public rewardFeeIn; // fee tier for rewardToken -> intermediary leg
    uint24 public rewardFeeOut; // fee tier for intermediary -> baseToken leg

    /**
     * @notice Ensures the caller is the strategy manager
     * @dev Reverts if caller is not the strategy manager
     */
    modifier onlyStrategyManager() {
        if (msg.sender != strategyManager) revert ErrorLibrary.CallerIsNotStrategyManager();
        _;
    }

    /**
     * @notice Ensures the protocol is not paused
     * @dev Reverts if protocol is paused
     */
    modifier whenNotPaused() {
        if (protocolRegistry.getProtocolState()) revert ErrorLibrary.ProtocolPaused();
        _;
    }

    modifier validSlippage(uint256 _slippage) {
        if (_slippage > MAX_SLIPPAGE) revert ErrorLibrary.InvalidSlippage();
        _;
    }

    /**
     * @notice Ensures the caller is the rewards claimer
     * @dev Reverts if caller is not the rewards claimer
     */
    modifier onlyRewardsClaimer() {
        if (msg.sender != protocolRegistry.getRewardsClaimer()) revert ErrorLibrary.CallerIsNotRewardsClaimer();
        _;
    }

    function initialize(
        address _protocolRegistry,
        address _baseToken,
        address _kodiakSwapRouter,
        address _islandRouter,
        address _island,
        address _hubVault,
        uint256 _fee
    ) external initializer {
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        __Ownable_init();
        protocolRegistry = IProtocolRegistry(_protocolRegistry);
        fee = _fee;
        baseToken = _baseToken;
        kodiakSwapRouter = _kodiakSwapRouter;
        islandRouter = _islandRouter;
        island = IKodiakIsland(_island);
        hubVault = IBGTGauge(_hubVault);
    }

    /********************/
    /* IStrategy Interface Implementation */
    /********************/

    function deposit(
        uint256 _amount,
        uint256 _slippage,
        uint256 _lpSlippage
    )
        public
        onlyStrategyManager
        nonReentrant
        whenNotPaused
        validSlippage(_slippage)
        validSlippage(_lpSlippage)
        returns (uint256, uint256)
    {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();
        IERC20Upgradeable(baseToken).safeTransferFrom(msg.sender, address(this), _amount);
        (uint256 amount, uint256 dustAmount) = _deposit(_amount, _slippage, msg.sender);
        IEventEmitter(protocolRegistry.getEventEmitter()).strategyDepositSuccessEvent(address(this), amount);
        return (amount, dustAmount);
    }

    /**
     * @notice Restricts base-token deposits to protocol-internal callers
     * @dev M-13: depositBase was permissionless, letting anyone donate into the
     *      strategy and inflate its reported NAV (feeding the share-price and
     *      recapitalization findings). Legitimate callers are the strategy manager,
     *      a sibling strategy routing its dust here, and the rewards claimer that
     *      compounds harvested rewards.
     */
    modifier onlyProtocolDepositor() {
        if (
            msg.sender != strategyManager &&
            msg.sender != protocolRegistry.getRewardsClaimer() &&
            !protocolRegistry.verifyProtocolStrategyAddress(msg.sender)
        ) revert ErrorLibrary.CallerIsNotStrategyManager();
        _;
    }

    /**
     * @notice Permissionless deposit entry used to absorb auto-compounded dust forwarded from a
     *         peer strategy. Caller must hold `baseToken` and have approved this contract for
     *         `_amount`. Behaves like `deposit` but without the StrategyManager role check; any
     *         residual dust still flows back to msg.sender.
     */
    function depositBase(uint256 _amount) external nonReentrant whenNotPaused onlyProtocolDepositor {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();
        IERC20Upgradeable(baseToken).safeTransferFrom(msg.sender, address(this), _amount);
        _deposit(_amount, 300, msg.sender);
    }

    function _deposit(
        uint256 _amount,
        uint256 _slippage,
        address _dustReceiver
    ) internal returns (uint256, uint256) {
        // M-13: snapshot inventory before any swap so the dust sweep below can
        // only return balances this call actually produced.
        uint256[] memory _dustRetained = new uint256[](2);
        {
            (IERC20 _t0, IERC20 _t1) = (island.token0(), island.token1());
            _dustRetained[0] = IERC20Upgradeable(address(_t0)).balanceOf(address(this));
            _dustRetained[1] = IERC20Upgradeable(address(_t1)).balanceOf(address(this));
        }
        IERC20Upgradeable(baseToken).safeApprove(kodiakSwapRouter, 0);
        IERC20Upgradeable(baseToken).safeApprove(kodiakSwapRouter, _amount);

        (uint256 swappedAmount0, uint256 swappedAmount1) = _performTokenSwaps(_amount, _slippage);
        (uint256 token0AmountMin, uint256 token1AmountMin, uint256 mintAmountMin) = island.getMintAmounts(
            swappedAmount0,
            swappedAmount1
        );

        _approveTokensForLiquidity(swappedAmount0, swappedAmount1);

        uint256 balanceBefore = IERC20Upgradeable(address(island)).balanceOf(address(this));
        uint256 balanceAssetsBefore = _getUnderlyingBalance(balanceBefore);

        uint256 islandTokenReceived = _addLiquidityToIsland(
            swappedAmount0,
            swappedAmount1,
            token0AmountMin,
            token1AmountMin,
            mintAmountMin
        );

        uint256 dustAmount = _handleDustAndStake(islandTokenReceived, _slippage, _dustReceiver, _dustRetained);
        uint256 balanceAssetsAfter = _getUnderlyingBalance(islandTokenReceived);

        return (balanceAssetsAfter - balanceAssetsBefore, dustAmount);
    }

    function _performTokenSwaps(
        uint256 _amount,
        uint256 _slippage
    ) internal returns (uint256 swappedAmount0, uint256 swappedAmount1) {
        (uint256 swapAmount0, uint256 swapAmount1) = getSwapAmounts(_amount);
        (IERC20 token0, IERC20 token1) = (island.token0(), island.token1());

        if (address(token0) == baseToken) {
            swappedAmount1 = IKodiakSwapController(kodiakSwapRouter).swap(
                address(token0),
                address(token1),
                swapAmount1,
                _getPoolFee(),
                _slippage
            );
            swappedAmount0 = swapAmount0;
        } else {
            swappedAmount0 = IKodiakSwapController(kodiakSwapRouter).swap(
                address(token1),
                address(token0),
                swapAmount0,
                _getPoolFee(),
                _slippage
            );
            swappedAmount1 = swapAmount1;
        }
    }

    function _approveTokensForLiquidity(uint256 _amount0, uint256 _amount1) internal {
        (IERC20 token0, IERC20 token1) = (island.token0(), island.token1());
        IERC20Upgradeable(address(token0)).safeApprove(islandRouter, 0);
        IERC20Upgradeable(address(token1)).safeApprove(islandRouter, 0);
        IERC20Upgradeable(address(token0)).safeApprove(islandRouter, _amount0);
        IERC20Upgradeable(address(token1)).safeApprove(islandRouter, _amount1);
    }

    function _addLiquidityToIsland(
        uint256 _amount0,
        uint256 _amount1,
        uint256 _amount0Min,
        uint256 _amount1Min,
        uint256 _mintAmountMin
    ) internal returns (uint256 islandTokenReceived) {
        (, , islandTokenReceived) = IIslandRouter(islandRouter).addLiquidity(
            island,
            _amount0,
            _amount1,
            _amount0Min,
            _amount1Min,
            _mintAmountMin,
            address(this)
        );
    }

    function _handleDustAndStake(
        uint256 _islandTokenReceived,
        uint256 _slippage,
        address _dustReceiver,
        uint256[] memory _retained
    ) internal returns (uint256 dustAmount) {
        (IERC20 token0, IERC20 token1) = (island.token0(), island.token1());
        address[] memory tokens = new address[](2);
        tokens[0] = address(token0);
        tokens[1] = address(token1);
        dustAmount = _checkForDust(tokens, _slippage, _dustReceiver, _retained);
        stake(_islandTokenReceived);
    }
    function withdraw(
        FunctionParameters.StrategyWithdrawParams memory _params,
        uint256 _slippage,
        uint256 _lpSlippage
    ) external onlyStrategyManager nonReentrant whenNotPaused validSlippage(_slippage) validSlippage(_lpSlippage) {
        uint256 balance = getTokenBalance();
        if (_params.strategyTokenAmount == 0) revert ErrorLibrary.InvalidAmount();
        IBGTGauge(hubVault).withdraw(_params.strategyTokenAmount);
        balance = IERC20Upgradeable(address(island)).balanceOf(address(this));
        if (balance == 0) revert ErrorLibrary.InvalidAmount();
        _withdraw(_params.strategyTokenAmount, _slippage, _lpSlippage);
    }

    function _withdraw(uint256 _amount, uint256 _slippage, uint256 _lpSlippage) internal {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();

        _removeLiquidityFromIsland(_amount, _lpSlippage);
        _swapTokensToBaseToken(_slippage);
        _transferBaseTokenToSender();
    }

    /**
     * @notice Removes liquidity from the Kodiak Island
     * @param _amount Amount of LP tokens to burn
     * @param _lpSlippage Slippage tolerance for liquidity removal
     */
    function _removeLiquidityFromIsland(uint256 _amount, uint256 _lpSlippage) internal {
        (uint256 amount0, uint256 amount1) = getLiquidityAmounts();
        uint256 totalSupply = IERC20Upgradeable(address(island)).totalSupply();

        IERC20Upgradeable(address(island)).safeApprove(islandRouter, 0);
        IERC20Upgradeable(address(island)).safeApprove(islandRouter, _amount);

        IIslandRouter(islandRouter).removeLiquidity(
            island,
            _amount,
            calculateSlippage((amount0 * _amount) / totalSupply, _lpSlippage),
            calculateSlippage((amount1 * _amount) / totalSupply, _lpSlippage),
            address(this)
        );
    }

    /**
     * @notice Swaps received tokens back to base token
     * @param _slippage Slippage tolerance for the swap
     */
    function _swapTokensToBaseToken(uint256 _slippage) internal {
        (IERC20 token0, IERC20 token1) = (island.token0(), island.token1());

        if (address(token0) == baseToken) {
            uint256 token1Balance = IERC20Upgradeable(address(token1)).balanceOf(address(this));
            IERC20Upgradeable(address(token1)).safeApprove(kodiakSwapRouter, 0);
            IERC20Upgradeable(address(token1)).safeApprove(kodiakSwapRouter, token1Balance);
            IKodiakSwapController(kodiakSwapRouter).swap(
                address(token1),
                address(token0),
                token1Balance,
                _getPoolFee(),
                _slippage
            );
        } else {
            uint256 token0Balance = IERC20Upgradeable(address(token0)).balanceOf(address(this));
            IERC20Upgradeable(address(token0)).safeApprove(kodiakSwapRouter, 0);
            IERC20Upgradeable(address(token0)).safeApprove(kodiakSwapRouter, token0Balance);
            IKodiakSwapController(kodiakSwapRouter).swap(
                address(token0),
                address(token1),
                token0Balance,
                _getPoolFee(),
                _slippage
            );
        }
    }

    /**
     * @notice Transfers base token to the sender and emits withdrawal event
     */
    function _transferBaseTokenToSender() internal {
        uint256 balance = IERC20Upgradeable(baseToken).balanceOf(address(this));
        IERC20Upgradeable(baseToken).safeTransfer(msg.sender, balance);
        IEventEmitter(protocolRegistry.getEventEmitter()).strategyWithdrawSuccessEvent(address(this), balance);
    }

    function getUnderlyingBalance() public view returns (uint256) {
        uint256 balance = getTokenBalance();
        if (balance == 0) return 0;
        return _getUnderlyingBalance(balance);
    }

    function _getUnderlyingBalance(uint256 _amount) internal view returns (uint256) {
        return
            StrategyLibrary.getKodiakUnderlyingBalanceOracle(
                _amount,
                island,
                baseToken,
                IPriceOracle(protocolRegistry.getOracle())
            );
    }

    /**
     * @notice Gets the token balance in the Hub vault
     * @return Balance of tokens in the vault
     */
    function getTokenBalance() public view returns (uint256) {
        return IBGTGauge(hubVault).balanceOf(address(this));
    }

    function getSwapAmounts(uint256 _amountIn) internal view returns (uint256 _swapAmount0, uint256 _swapAmount1) {
        (uint256 amount0, uint256 amount1) = getLiquidityAmounts();
        (IERC20 token0, IERC20 token1) = (island.token0(), island.token1());
        uint256 token0Price = IPriceOracle(protocolRegistry.getOracle()).getPriceTokenUSD18Decimals(
            address(token0),
            amount0
        );
        uint256 token1Price = IPriceOracle(protocolRegistry.getOracle()).getPriceTokenUSD18Decimals(
            address(token1),
            amount1
        );
        if (address(token0) == baseToken) {
            (_swapAmount0, _swapAmount1) = _divideAmountInRatio(_amountIn, token0Price, token1Price);
        } else {
            // Base is token1: the first share (weighted by token1's value) is the base
            // amount KEPT as token1; the second is what gets swapped into token0.
            // Assigning them the other way round swapped the island's majority side,
            // so most of each deposit came back as dust.
            (_swapAmount1, _swapAmount0) = _divideAmountInRatio(_amountIn, token1Price, token0Price);
        }
    }

    function getLiquidityAmounts() internal view returns (uint256 amount0, uint256 amount1) {
        (amount0, amount1) = island.getUnderlyingBalances();
    }

    function _getPoolFee() internal view returns (uint24) {
        return island.pool().fee();
    }

    function calculateSlippage(uint256 _amountIn, uint256 _slippage) internal pure returns (uint256) {
        return (_amountIn * (10000 - _slippage)) / 10000;
    }

    /**
     * @notice Stakes tokens in the Hub vault
     * @param _amount Amount of tokens to stake
     */
    function stake(uint256 _amount) internal {
        if (_amount == 0) revert ErrorLibrary.InvalidAmount();
        IERC20Upgradeable(address(island)).safeApprove(address(hubVault), 0);
        IERC20Upgradeable(address(island)).safeApprove(address(hubVault), type(uint256).max);

        hubVault.stake(_amount);
    }

    function _divideAmountInRatio(
        uint256 amount,
        uint256 ratio0,
        uint256 ratio1
    ) internal pure returns (uint256, uint256) {
        uint256 totalRatio = ratio0 + ratio1;
        if (totalRatio == 0) revert ErrorLibrary.TotalZero();
        uint256 amount0 = (amount * ratio0) / totalRatio;
        uint256 amount1 = amount - amount0;
        return (amount0, amount1);
    }

    /**
     * @notice Sets the strategy manager address
     * @param _strategyManager Address of the strategy manager
     */
    function setStrategyManager(address _strategyManager) public onlyOwner {
        if (_strategyManager == address(0)) revert ErrorLibrary.InvalidAddress();
        strategyManager = _strategyManager;
    }

    /**
     * @notice Gets the reward tokens from the Hub vault
     * @return Array of reward token addresses
     */
    function rewardToken() public view returns (address[] memory) {
        address[] memory rewardTokens = new address[](1);
        rewardTokens[0] = WBERA;
        return rewardTokens;
    }

    function _checkForDust(
        address[] memory _tokens,
        uint256 _slippage,
        address _sender,
        uint256[] memory _retained
    ) internal returns (uint256) {
        uint256 dustAmount = 0;
        for (uint256 i = 0; i < _tokens.length; i++) {
            uint256 tokenBalance = IERC20Upgradeable(_tokens[i]).balanceOf(address(this));
            // M-13: only sweep what THIS call created; never pre-existing inventory.
            uint256 retained = i < _retained.length ? _retained[i] : 0;
            tokenBalance = tokenBalance > retained ? tokenBalance - retained : 0;
            if (tokenBalance == 0) continue;
            if (_tokens[i] == baseToken) {
                IERC20Upgradeable(_tokens[i]).safeTransfer(_sender, tokenBalance);
                dustAmount += tokenBalance;
            } else {
                IERC20Upgradeable(_tokens[i]).safeApprove(kodiakSwapRouter, 0);
                IERC20Upgradeable(_tokens[i]).safeApprove(kodiakSwapRouter, tokenBalance);
                IKodiakSwapController(kodiakSwapRouter).swap(
                    _tokens[i],
                    baseToken,
                    tokenBalance,
                    _getPoolFee(),
                    _slippage
                );
                uint256 swapAmount = IERC20Upgradeable(baseToken).balanceOf(address(this));
                IERC20Upgradeable(baseToken).safeTransfer(_sender, swapAmount);
                dustAmount += swapAmount;
            }
        }
        return dustAmount;
    }

    function getReward(
        uint256 _slippage
    ) external nonReentrant whenNotPaused onlyRewardsClaimer validSlippage(_slippage) {
        _harvest(_slippage);
    }

    /**
     * @notice Uniform harvest entry point called by the StrategyManager during
     *         _updateInvestment, so pending rewards are compounded into the
     *         balance before the vault reads it.
     * @dev `_lpSlippage` is unused here: this strategy has no LP leg. Guarded by
     *      onlyStrategyManager in addition to the claimer path above.
     */
    function harvest(uint256 _slippage, uint256 _lpSlippage) external nonReentrant whenNotPaused validSlippage(_slippage) {
        if (msg.sender != strategyManager && msg.sender != protocolRegistry.getRewardsClaimer())
            revert ErrorLibrary.CallerIsNotStrategyManager();
        _harvest(_slippage);
    }

    /// @dev Shared body. Internal so both entry points reuse it without
    ///      re-entering the contract's own nonReentrant guard.
    function _harvest(uint256 _slippage) internal {
        if (_slippage > 300) revert ErrorLibrary.InvalidSlippage();
        address[] memory rewardTokens = new address[](1);
        rewardTokens[0] = WBERA;
        IBGTGauge(hubVault).getReward(address(this), address(this));

        uint256 totalBaseTokenAmount = 0;
        uint256[] memory rewardAmounts = new uint256[](rewardTokens.length);

        for (uint256 i = 0; i < rewardTokens.length; i++) {
            uint256 balance = IERC20Upgradeable(rewardTokens[i]).balanceOf(address(this));
            if (balance == 0) continue;

            rewardAmounts[i] = balance;

            if (rewardTokens[i] == baseToken) {
                // Already base token, just add to total
                totalBaseTokenAmount += balance;
            } else {
                // Swap reward token to base token using kodiak swap.
                IERC20Upgradeable(rewardTokens[i]).safeApprove(kodiakSwapRouter, 0);
                IERC20Upgradeable(rewardTokens[i]).safeApprove(kodiakSwapRouter, balance);

                uint256 baseTokenReceived;
                if (rewardIntermediaryToken == address(0)) {
                    // Direct single-hop swap rewardToken -> baseToken.
                    baseTokenReceived = IKodiakSwapController(kodiakSwapRouter).swap(
                        rewardTokens[i],
                        baseToken,
                        balance,
                        uint24(fee),
                        _slippage
                    );
                } else {
                    // Multi-hop swap rewardToken -> intermediary -> baseToken (no liquid direct pool).
                    baseTokenReceived = IKodiakSwapController(kodiakSwapRouter).swapWithIntermediary(
                        rewardTokens[i],
                        rewardIntermediaryToken,
                        baseToken,
                        balance,
                        rewardFeeIn,
                        rewardFeeOut,
                        _slippage
                    );
                }
                totalBaseTokenAmount += baseTokenReceived;
            }
        }

        // Compound rewards back into this strategy. Dust receiver is set to address(this) so
        // any residual base token from _handleDustAndStake stays on this contract instead of
        // being sent to the rewards-claimer EOA. The leftover is then forwarded into the
        // configured dust strategy via depositBase.
        uint256 receiptTokenAmount = 0;
        uint256 dustAmount = 0;
        if (totalBaseTokenAmount > 0) {
            uint256 HubBalanceBefore = IBGTGauge(hubVault).balanceOf(address(this));
            _deposit(totalBaseTokenAmount, _slippage, address(this));
            receiptTokenAmount = IBGTGauge(hubVault).balanceOf(address(this)) - HubBalanceBefore;

            dustAmount = IERC20Upgradeable(baseToken).balanceOf(address(this));
            if (dustAmount > 0) {
                address dustStrategy = IStrategyManager(strategyManager).dustStrategy();
                if (dustStrategy == address(0)) revert ErrorLibrary.InvalidAddress();
                IERC20Upgradeable(baseToken).safeApprove(dustStrategy, 0);
                IERC20Upgradeable(baseToken).safeApprove(dustStrategy, dustAmount);
                IStrategyDustReceiver(dustStrategy).depositBase(dustAmount);
            }
        }

        IEventEmitter(protocolRegistry.getEventEmitter()).strategyRewardClaimedEvent(
            address(this),
            rewardTokens,
            rewardAmounts,
            totalBaseTokenAmount,
            receiptTokenAmount,
            dustAmount
        );
    }

    function updateFee(uint256 _fee) external onlyOwner {
        if (_fee > type(uint24).max || _fee == 0) revert ErrorLibrary.InvalidFee();
        fee = _fee;
    }

    /**
     * @notice Configures the multi-hop reward swap route (rewardToken -> intermediary -> baseToken).
     * @dev When set, getReward routes reward swaps through `_intermediary` instead of the direct pool.
     *      Both fee tiers must be non-zero. Use `clearRewardIntermediary` to revert to direct swaps.
     * @param _intermediary Intermediary hop token (e.g. WBERA)
     * @param _feeIn Pool fee tier for the rewardToken -> intermediary leg
     * @param _feeOut Pool fee tier for the intermediary -> baseToken leg
     */
    function setRewardIntermediary(address _intermediary, uint24 _feeIn, uint24 _feeOut) external onlyOwner {
        if (_intermediary == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_feeIn == 0 || _feeOut == 0) revert ErrorLibrary.InvalidFee();
        rewardIntermediaryToken = _intermediary;
        rewardFeeIn = _feeIn;
        rewardFeeOut = _feeOut;
    }

    /**
     * @notice Clears the multi-hop reward route so getReward falls back to direct single-hop swaps.
     */
    function clearRewardIntermediary() external onlyOwner {
        rewardIntermediaryToken = address(0);
        rewardFeeIn = 0;
        rewardFeeOut = 0;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
}

