// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {StablePoolUserDataHubLibrary} from "./StablePoolUserDataHubLibrary.sol";
import {IBeraHub} from "../../interfaces/external/bera/IBeraHub.sol";
import {IBeraPool} from "../../interfaces/strategy/IBeraPool.sol";
import {IPriceOracle} from "../../interfaces/core/IPriceOracle.sol";
import {IERC20MetadataUpgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/IERC20MetadataUpgradeable.sol";
import {LogExpMath} from "../../library/math/LogExpMath.sol";
import {FixedPoint} from "../../library/math/FixedPoint.sol";
import {IKodiakIsland} from "../../interfaces/strategy/IKodiakIsland.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {FullMath} from "@uniswap/v3-core/contracts/libraries/FullMath.sol";

library StrategyLibrary {
    error BaseTokenNotFound();
    error InvalidOracleRatio();
    using SafeERC20 for IERC20;
    using LogExpMath for uint256;
    using FixedPoint for uint256;

    struct PoolData {
        IERC20[] tokens;
        uint256[] balances;
        address pool;
    }

    function transferAndApproveBaseToken(address baseToken, address vault, uint256 amount) internal {
        IERC20(baseToken).safeTransferFrom(msg.sender, address(this), amount);
        IERC20(baseToken).safeApprove(vault, 0);
        IERC20(baseToken).safeApprove(vault, amount);
    }

    function buildDepositArrays(
        IERC20[] memory tokens,
        address bptToken,
        address baseToken,
        uint256 amount
    )
        internal
        pure
        returns (
            address[] memory assetAddresses,
            uint256[] memory maxAmountsIn,
            uint256[] memory amountsIn,
            uint256 baseIndex
        )
    {
        uint256 tokenCount = tokens.length;
        assetAddresses = new address[](tokenCount);
        maxAmountsIn = new uint256[](tokenCount);
        amountsIn = new uint256[](tokenCount == 2 ? tokenCount : tokenCount - 1);
        baseIndex = type(uint256).max;
        uint256 j = 0;

        for (uint256 i = 0; i < tokenCount; i++) {
            address token = address(tokens[i]);
            assetAddresses[i] = token;
            if (token == baseToken) {
                baseIndex = i;
                maxAmountsIn[i] = amount;
                amountsIn[j] = amount;
                j++;
            } else if (token == bptToken) {
                maxAmountsIn[i] = 0;
            } else {
                maxAmountsIn[i] = 0;
                amountsIn[j] = 0;
                j++;
            }
        }
    }

    function encodeJoinUserData(uint256[] memory amountsIn, uint256 minimumBPT) internal pure returns (bytes memory) {
        return abi.encode(StablePoolUserDataHubLibrary.JoinKind.EXACT_TOKENS_IN_FOR_LP_OUT, amountsIn, minimumBPT);
    }

    function buildJoinPoolRequest(
        address[] memory assetAddresses,
        uint256[] memory maxAmountsIn,
        bytes memory userData
    ) internal pure returns (IBeraHub.JoinPoolRequest memory) {
        return
            IBeraHub.JoinPoolRequest({
                assets: assetAddresses,
                maxAmountsIn: maxAmountsIn,
                userData: userData,
                fromInternalBalance: false
            });
    }

    function buildWithdrawArrays(
        IERC20[] memory poolTokens,
        address pool,
        address baseToken,
        uint256 minimumTokenOut
    ) internal pure returns (address[] memory tokens, uint256[] memory tokenAmounts, uint256 baseIndex) {
        uint256 tokenLength = poolTokens.length;
        baseIndex = type(uint256).max;
        tokenAmounts = new uint256[](tokenLength);
        tokens = new address[](tokenLength);
        uint256 j = 0;

        for (uint256 i = 0; i < tokenLength; i++) {
            tokens[i] = address(poolTokens[i]);
            if (tokens[i] != pool) {
                if (tokens[i] == baseToken) {
                    // Exit user data indexes only the non-pool tokens, while
                    // minAmountsOut indexes the complete assets array.
                    baseIndex = j;
                    tokenAmounts[i] = minimumTokenOut;
                }
                j++;
            }
        }

        if (baseIndex == type(uint256).max) revert BaseTokenNotFound();
    }

    function encodeExitUserData(uint256 amount, uint256 baseIndex) internal pure returns (bytes memory) {
        return abi.encode(StablePoolUserDataHubLibrary.ExitKind.EXACT_LP_IN_FOR_ONE_TOKEN_OUT, amount, baseIndex);
    }

    function buildExitPoolRequest(
        address[] memory tokens,
        uint256[] memory tokenAmounts,
        bytes memory userData
    ) internal pure returns (IBeraHub.ExitPoolRequest memory) {
        return
            IBeraHub.ExitPoolRequest({
                assets: tokens,
                minAmountsOut: tokenAmounts,
                userData: userData,
                toInternalBalance: false
            });
    }

    function calculateMinimumBPT(
        IERC20[] memory tokens,
        uint256[] memory balances,
        address poolAddress,
        address baseToken,
        uint256 amountIn,
        uint256 slippageBps,
        IPriceOracle priceOracle
    ) internal view returns (uint256) {
        require(slippageBps <= 10_000, "Slippage too high");

        uint256 totalBPTSupply = IBeraPool(poolAddress).getActualSupply();
        uint256 tokenInValueUSD = priceOracle.getPriceTokenUSD18Decimals(baseToken, amountIn);
        uint256 totalPoolValueUSD = 0;

        for (uint256 i = 0; i < tokens.length; i++) {
            if (address(tokens[i]) != poolAddress) {
                totalPoolValueUSD += priceOracle.getPriceTokenUSD18Decimals(address(tokens[i]), balances[i]);
            }
        }

        uint256 estimatedBPTOut = (tokenInValueUSD * totalBPTSupply) / totalPoolValueUSD;
        return applySlippage(estimatedBPTOut, slippageBps);
    }

    function calculateMinimumTokenOut(
        IERC20[] memory tokens,
        uint256[] memory balances,
        address poolAddress,
        address baseToken,
        uint256 bptAmountIn,
        uint256 slippageBps,
        IPriceOracle priceOracle
    ) internal view returns (uint256) {
        require(slippageBps <= 10_000, "Slippage too high");
        uint256 totalBPTSupply = IBeraPool(poolAddress).getActualSupply();
        require(totalBPTSupply > 0, "Invalid pool or token");

        uint256 tokenIndex = type(uint256).max;
        for (uint256 i = 0; i < tokens.length; i++) {
            if (address(tokens[i]) == baseToken) {
                tokenIndex = i;
                break;
            }
        }

        uint256 totalPoolValue = 0;
        for (uint256 i = 0; i < tokens.length; i++) {
            if (address(tokens[i]) != poolAddress) {
                totalPoolValue += priceOracle.getPriceForTokenAmount(address(tokens[i]), baseToken, balances[i]);
            }
        }

        uint256 estimatedTokenOut = (bptAmountIn * totalPoolValue) / totalBPTSupply;
        return applySlippage(estimatedTokenOut, slippageBps);
    }

    function applySlippage(uint256 expectedAmount, uint256 slippageBps) internal pure returns (uint256) {
        return (expectedAmount * (10_000 - slippageBps)) / 10_000;
    }

    function getUnderlyingBalance(
        uint256 balanceBPT,
        IERC20[] memory tokens,
        uint256[] memory balances,
        address pool,
        address baseToken,
        IPriceOracle priceOracle
    ) internal view returns (uint256) {
        return _getUnderlyingBalanceOracle(balanceBPT, tokens, balances, pool, baseToken, priceOracle);
    }

    function _getUnderlyingBalanceOracle(
        uint256 balanceBPT,
        IERC20[] memory tokens,
        uint256[] memory balances,
        address pool,
        address baseToken,
        IPriceOracle priceOracle
    ) internal view returns (uint256) {
        if (balanceBPT == 0) {
            return 0;
        }

        uint256 totalSupplyBPT = IBeraPool(pool).getActualSupply();

        uint256 priceBPT = 0;
        for (uint256 i = 0; i < tokens.length; i++) {
            if (address(tokens[i]) != address(pool)) {
                uint256 tokenEquivalent = (balanceBPT * balances[i]) / totalSupplyBPT;
                if (address(tokens[i]) == baseToken) {
                    priceBPT += tokenEquivalent;
                } else {
                    uint256 priceEquivalent = priceOracle.getPriceForTokenAmount(
                        address(tokens[i]),
                        baseToken,
                        tokenEquivalent
                    );
                    priceBPT += priceEquivalent;
                }
            }
        }
        return priceBPT;
    }

    function getKodiakUnderlyingBalanceOracle(
        uint256 islandAmount,
        IKodiakIsland island,
        address baseToken,
        IPriceOracle priceOracle
    ) internal view returns (uint256) {
        if (islandAmount == 0) return 0;

        address token0 = address(island.token0());
        address token1 = address(island.token1());
        uint8 decimals0 = IERC20MetadataUpgradeable(token0).decimals();
        uint8 decimals1 = IERC20MetadataUpgradeable(token1).decimals();
        if (decimals0 > 18 || decimals1 > 18) revert InvalidOracleRatio();

        uint256 price0 = priceOracle.getPriceTokenUSD18Decimals(token0, 10 ** decimals0);
        uint256 price1 = priceOracle.getPriceTokenUSD18Decimals(token1, 10 ** decimals1);
        if (price0 == 0 || price1 == 0) revert InvalidOracleRatio();

        // Uniswap sqrtPriceX96 represents sqrt(raw token1 / raw token0).
        // Computed as sqrt(ratio * 2^128) * 2^32 rather than via a 1e18 ratio:
        // with an 18-decimal token0 and a 6- or 8-decimal token1 the raw ratio is
        // ~1e-12, so a 1e18 fixed point kept only a few digits and floored the
        // price by several percent. Q128 keeps ~13 digits there and only
        // overflows past ratio 2^128, already outside the valid sqrt-price range.
        uint256 ratioX128 = FullMath.mulDiv(
            price0 * (10 ** decimals1),
            2 ** 128,
            price1 * (10 ** decimals0)
        );
        uint256 sqrtRatioX96 = Math.sqrt(ratioX128) << 32;
        if (sqrtRatioX96 == 0 || sqrtRatioX96 > type(uint160).max) revert InvalidOracleRatio();

        (uint256 amount0, uint256 amount1) = island.getUnderlyingBalancesAtPrice(uint160(sqrtRatioX96));
        uint256 totalSupply = island.totalSupply();
        if (totalSupply == 0) return 0;

        uint256 share0 = FullMath.mulDiv(amount0, islandAmount, totalSupply);
        uint256 share1 = FullMath.mulDiv(amount1, islandAmount, totalSupply);
        uint256 value0 = token0 == baseToken
            ? share0
            : priceOracle.getPriceForTokenAmount(token0, baseToken, share0);
        uint256 value1 = token1 == baseToken
            ? share1
            : priceOracle.getPriceForTokenAmount(token1, baseToken, share1);
        return value0 + value1;
    }
}

