pragma solidity 0.8.30;

interface IBGTGauge {
    function stake(uint256 amount) external;
    function withdraw(uint256 amount) external;
    function getReward(address account, address recipient) external returns (uint256);
    function balanceOf(address user) external view returns (uint256);

    /**
     * @notice Rewards accrued to `account` but not yet claimed.
     * @dev View, so NAV can include pending rewards without simulating a claim.
     *      The name is historical — these gauges distribute WBERA, not BGT, so
     *      callers must read `rewardToken()` rather than assuming the asset.
     */
    function earned(address account) external view returns (uint256);

    /// @notice The token this gauge pays out. WBERA on the live Bera gauges.
    function rewardToken() external view returns (address);
}

