contracts/library/core/ErrorLibrary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

/**
 * @title ErrorLibrary
 * @author Berafarm
 * @notice This is a library contract including custom defined errors for the protocol
 * @dev All errors are organized by category and include detailed NatSpec documentation
 */

library ErrorLibrary {
    /********************/
    /* Common Errors */
    /********************/

    /// @notice Thrown when an amount is invalid (e.g., zero or exceeds limits)
    error InvalidAmount();

    /// @notice Thrown when depositing into a zero-value tranche with outstanding shares
    error TrancheWipedOut();

    /// @notice Thrown when a final withdrawal would abandon assets in a paused strategy
    error PausedStrategyHasAssets();

    /// @notice Empty vault assets must be resolved before accepting new principal
    error ResidualVaultAssets();

    /// @notice A deposit cannot route returned dust to an inactive strategy
    error InactiveDustStrategy();

    /// @notice Thrown when an address is invalid (e.g., zero address)
    error InvalidAddress();

    /// @notice Thrown when slippage is invalid (e.g., exceeds maximum allowed)
    error InvalidSlippage();

    /// @notice Thrown when LP slippage is invalid (e.g., exceeds maximum allowed)
    error InvalidLPSlippage();

    /// @notice Thrown when there is insufficient balance for an operation
    error InsufficientBalance();

    /// @notice Thrown when there are insufficient funds for an operation
    /// @param available The amount of funds available
    /// @param required The amount of funds required
    error InsufficientFunds(uint256 available, uint256 required);

    /// @notice Thrown when a transfer operation fails
    error TransferFailed();

    /// @notice Thrown when a call operation fails
    error CallFailed();

    /// @notice Thrown when a reentrant call is detected
    error ReentrancyGuardReentrantCall();

    /********************/
    /* Access Control Errors */
    /********************/

    /// @notice Thrown when the caller is not the owner
    error CallerNotOwner();

    /// @notice Thrown when the caller is not an admin
    error CallerNotAdmin();

    /// @notice Thrown when the caller is not a minter
    error CallerNotMinter();

    /// @notice Thrown when the caller is not a handler contract
    error CallerNotHandlerContract();

    /// @notice Thrown when the caller is not an off-chain contract
    error CallerNotOffChainContract();

    /// @notice Thrown when the caller is not a rebalancer contract
    error CallerNotRebalancerContract();

    /// @notice Thrown when the caller is not an asset manager
    error CallerNotAssetManager();

    /// @notice Thrown when the caller is not a super admin
    error CallerNotSuperAdmin();

    /// @notice Thrown when the caller is not a whitelist manager
    error CallerNotWhitelistManager();

    /// @notice Thrown when the caller is not an index manager
    error CallerNotIndexManager();

    /// @notice Thrown when the caller is not a fee module
    error CallerNotFeeModule();

    /// @notice Thrown when the caller is not a vault manager
    error CallerIsNotVaultManager();

    /// @notice Thrown when the caller is not a tranche vault manager
    error CallerIsNotTrancheVaultManager();

    /// @notice Thrown when the caller is not a fee minter
    error CallerIsNotFeeMinter();

    /// @notice Thrown when the caller is not a bot role
    error CallerIsNotBotRole();

    /// @notice Thrown when the caller is not a strategy manager
    error CallerIsNotStrategyManager();

    /// @notice Thrown when the caller is not a governor
    error CallerIsNotGovernor();

    /// @notice Thrown when the caller is not a tranche vault
    error CallerIsNotTrancheVault();

    /// @notice Thrown when the caller is not a protocol manager
    error CallerIsNotProtocolManager();

    /// @notice Thrown when the caller is not a reward distributor
    error CallerIsNotRewardDistributor();

    /// @notice Thrown when the caller is not a tranche vault admin
    error CallerIsNotTrancheVaultAdmin();

    /// @notice Thrown when the caller is not a strategy manager admin
    error CallerIsNotStrategyManagerAdmin();

    /// @notice Thrown when the caller is not a protocol manager admin
    error CallerIsNotProtocolManagerAdmin();

    /// @notice Thrown when the caller is not a whitelist manager admin
    error CallerIsNotWhitelistManagerAdmin();

    /// @notice Thrown when the caller is not a reward distributor admin
    error CallerIsNotRewardDistributorAdmin();

    /********************/
    /* Protocol State Errors */
    /********************/

    /// @notice Thrown when the contract is paused
    error ContractPaused();

    /// @notice Thrown when the contract is not paused
    error ContractNotPaused();

    /// @notice Thrown when the protocol is paused
    error ProtocolPaused();

    /// @notice Thrown when the protocol is not paused
    error ProtocolNotPaused();

    /// @notice Thrown when the protocol is paused
    error ProtocolIsPaused();

    /// @notice Thrown when index creation is paused
    error IndexCreationIsPaused();

    /// @notice Thrown when there is already an ongoing operation
    error AlreadyOngoingOperation();

    /********************/
    /* Token Related Errors */
    /********************/

    /// @notice Thrown when a token is not permitted
    error TokenNotPermitted();

    /// @notice Thrown when a token is not whitelisted
    error TokenNotWhitelisted();

    /// @notice Thrown when a token is not enabled
    error TokenNotEnabled();

    /// @notice Thrown when a token is not an index token
    error TokenNotIndexToken();

    /// @notice Thrown when a token is not a primary token
    error TokenNotPrimary();

    /// @notice Thrown when a token is not ETH
    error TokenNotETH();

    /// @notice Thrown when a token is not a V token
    error TokenNotVToken();

    /// @notice Thrown when a token is not a reward token
    error TokenNotRewardToken();

    /// @notice Thrown when a token is not approved
    error TokenNotApproved();

    /// @notice Thrown when a token already exists
    error TokenAlreadyExist();

    /// @notice Thrown when a token is already redeemed
    error TokenAlreadyRedeemed();

    /// @notice Thrown when tokens are not redeemed
    error TokensNotRedeemed();

    /// @notice Thrown when tokens are staked
    error TokensStaked();

    /// @notice Thrown when tokens are not staked
    error TokensNotStaked();

    /// @notice Thrown when LP balance is zero
    error LpBalanceZero();

    /********************/
    /* Price Oracle Errors */
    /********************/

    /// @notice Thrown when the price oracle data is expired
    error PriceOracleExpired();

    /// @notice Thrown when the price oracle data is invalid
    error PriceOracleInvalid();

    /// @notice Thrown when a token is not in the price oracle
    error TokenNotInPriceOracle();

    /// @notice Thrown when an aggregator already exists
    error AggregatorAlreadyExists();

    /// @notice Thrown when a feed is not found
    error FeedNotFound();

    /********************/
    /* Array Length Errors */
    /********************/

    /// @notice Thrown when array lengths are incorrect
    error IncorrectArrayLength();

    /// @notice Thrown when a length is invalid
    error InvalidLength();

    /// @notice Thrown when slippage length is invalid
    error InvalidSlippageLength();

    /// @notice Thrown when initialization input is invalid
    error InvalidInitInput();

    /// @notice Thrown when denorms are invalid
    error InvalidDenorms();

    /// @notice Thrown when threshold length is invalid
    error InvalidThresholdLength();

    /// @notice Thrown when token length is invalid
    error InvalidTokenLength();

    /// @notice Thrown when lengths don't match
    error LengthsDontMatch();

    /********************/
    /* Investment Related Errors */
    /********************/

    /// @notice Thrown when investment amount is wrong
    /// @param minInvestment The minimum investment amount
    /// @param maxInvestment The maximum investment amount
    error WrongInvestmentAmount(uint256 minInvestment, uint256 maxInvestment);

    /// @notice Thrown when minimum investment amount is invalid
    error InvalidMinInvestmentAmount();

    /// @notice Thrown when maximum investment amount is invalid
    error InvalidMaxInvestmentAmount();

    /// @notice Thrown when user is not allowed to invest
    error UserNotAllowedToInvest();

    /// @notice Thrown when user is not whitelisted
    error UserNotWhitelisted();

    /// @notice Thrown when user balance is not enough
    error UserBalanceNotEnough();

    /// @notice Thrown when user max deposit limit is reached
    error UserMaxDepositLimit();

    /// @notice Thrown when vault max TVL limit is reached
    error VaultMaxTvlLimit();

    /// @notice Thrown when a tranche's own deposit cap would be exceeded
    error TrancheMaxLimit();

    /// @notice Thrown when balance is too small
    error BalanceTooSmall();

    /// @notice Thrown when balance is below minimum Velvet investment amount
    /// @param minVelvetInvestment The minimum Velvet investment amount
    error BalanceCantBeBelowVelvetMinInvestAmount(uint256 minVelvetInvestment);

    /********************/
    /* Swap Related Errors */
    /********************/

    /// @notice Thrown when swap operation fails
    error SwapFailed();

    /// @notice Thrown when swap handler is not enabled
    error SwapHandlerNotEnabled();

    /// @notice Thrown when swap handler is not valid
    error SwapHandlerNotValid();

    /// @notice Thrown when buy token address is not valid
    error BuyTokenAddressNotValid();

    /// @notice Thrown when buy and sell tokens are the same
    error BuyAndSellTokenAreSame();

    /// @notice Thrown when input token list is invalid
    error InvalidInputTokenList();

    /// @notice Thrown when zero tokens are swapped
    error ZeroTokensSwapped();

    /// @notice Thrown when investment token amount is incorrect
    error IncorrectInvestmentTokenAmount();

    /// @notice Thrown when invested amount after slippage is zero
    error ZeroInvestedAmountAfterSlippage();

    /// @notice Thrown when slippage range is incorrect
    error IncorrectSlippageRange();

    /********************/
    /* Protocol Specific Errors */
    /********************/

    /// @notice Thrown when there is not enough balance in Alpaca protocol
    error NotEnoughBalanceInAlpacaProtocol();

    /// @notice Thrown when there is not enough balance in ApeSwap
    error NotEnoughBalanceInApeSwap();

    /// @notice Thrown when there is not enough balance in Beefy protocol
    error NotEnoughBalanceInBeefyProtocol();

    /// @notice Thrown when there is not enough balance in Beefy
    error NotEnoughBalanceInBeefy();

    /// @notice Thrown when there is not enough balance in BiSwap protocol
    error NotEnoughBalanceInBiSwapProtocol();

    /// @notice Thrown when there is not enough balance in Liqee protocol
    error NotEnoughBalanceInLiqeeProtocol();

    /// @notice Thrown when there is not enough balance in Pancake protocol
    error NotEnoughBalanceInPancakeProtocol();

    /// @notice Thrown when there is not enough balance in Wombat protocol
    error NotEnoughBalanceInWombatProtocol();

    /// @notice Thrown when there is not enough BNB
    error NotEnoughBNB();

    /// @notice Thrown when there is insufficient token A balance
    error InsufficientTokenABalance();

    /// @notice Thrown when there is insufficient token B balance
    error InsufficientTokenBBalance();

    /// @notice Thrown when there are insufficient fee funds
    /// @param available The amount of fee funds available
    /// @param required The amount of fee funds required
    error InsufficientFeeFunds(uint256 available, uint256 required);

    /// @notice Thrown when currency is not WNative
    error CurrencyNotWNative();

    /// @notice Thrown when message value does not match
    error MessageValueNotMatched();

    /// @notice Thrown when tranche ID is invalid
    error TrancheIdInvalid();

    /// @notice Thrown when total is zero
    error TotalZero();

    /********************/
    /* Other Errors */
    /********************/

    /// @notice Thrown when contract is already initialized
    error AlreadyInitialized();

    /// @notice Thrown when contract is not initialized
    error NotInitialized();

    /// @notice Thrown when already redeemed
    error AlreadyRedeemed();

    /// @notice Thrown when not redeemed
    error NotRedeemed();

    /// @notice Thrown when execution is invalid
    error InvalidExecution();

    /// @notice Thrown when final investment value is zero
    error ZeroFinalInvestmentValue();

    /// @notice Thrown when token amount is zero
    error ZeroTokenAmount();

    /// @notice Thrown when ETH transfer fails
    error ETHTransferFailed();

    /// @notice Thrown when wrong native value is passed
    error WrongNativeValuePassed();

    /// @notice Thrown when full division overflows
    error FULLDIV_OVERFLOW();

    /// @notice Thrown when no new fee is set
    error NoNewFeeSet();

    /// @notice Thrown when public fund to whitelisted is not allowed
    error PublicFundToWhitelistedNotAllowed();

    /// @notice Thrown when implementation is not correct
    error ImplementationNotCorrect();

    /// @notice Thrown when treasury address is zero
    error ZeroAddressTreasury();

    /// @notice Thrown when fee is zero
    error ZeroFee();

    /// @notice Thrown when handler is already enabled
    error HandlerAlreadyEnabled();

    /// @notice Thrown when handler is already disabled
    error HandlerAlreadyDisabled();

    /// @notice Thrown when oracle address is invalid
    error InvalidOracleAddress();

    /// @notice Thrown when handler address is invalid
    error InvalidHandlerAddress();

    /// @notice Thrown when PID is invalid
    error InvalidPID();

    /// @notice Thrown when out asset is invalid
    error InvalidOutAsset();

    /// @notice Thrown when sell amount is invalid
    error InvalidSellAmount();

    /// @notice Thrown when withdraw transfer fails
    error WithdrawTransferFailed();

    /// @notice Thrown when denorm value is zero
    error ZeroDenormValue();

    /// @notice Thrown when cool down period has not passed
    error CoolDownPeriodNotPassed();

    /// @notice Thrown when fifteen minutes have not exceeded
    error FifteenMinutesNotExcedeed();

    /// @notice Thrown when time period is not over
    error TimePeriodNotOver();

    /// @notice Thrown when fee is invalid
    error InvalidFee();

    /// @notice Thrown when weight is not greater than 0
    error WeightNotGreaterThan0();

    /// @notice Thrown when division by zero sum weight occurs
    error DivBy0Sumweight();

    /// @notice Thrown when off handler is not valid
    error OffHandlerNotValid();

    /// @notice Thrown when off handler is not enabled
    error OffHandlerNotEnabled();

    /// @notice Thrown when swap handler is not enabled
    error SwaphandlerNotEnabled();

    /// @notice Thrown when only asset manager can call
    error OnlyAssetManagerCanCall();

    /// @notice Thrown when only asset manager can call unpause
    error OnlyAssetManagerCanCallUnpause();

    /// @notice Thrown when module is not initialized
    error ModuleNotInitialised();

    /// @notice Thrown when no owner is passed
    error NoOwnerPassed();

    /// @notice Thrown when buy values are invalid
    error InvalidBuyValues();

    /// @notice Thrown when token out is not permitted
    error _tokenOutNotPermitted();

    /// @notice Thrown when weight input is wrong
    error WrongWeightInput();

    /// @notice Thrown when token input is wrong
    error WrongTokenInput();

    /// @notice Thrown when token out input is wrong
    error WrongTokenOutInput();

    /// @notice Thrown when token in input is wrong
    error WrongTokenInInput();

    /// @notice Thrown when merkle root is invalid
    error InvalidMerkleRoot();

    /// @notice Thrown when merkle proof is invalid
    error InvalidMerkleProof();

    /// @notice Thrown when pool is invalid
    error InvalidPool();

    /// @notice Thrown when caller is not a rewards claimer
    error CallerIsNotRewardsClaimer();
}

