pragma solidity 0.8.30;

library FunctionParameters {
    struct StrategyInfo {
        address strategy;
        uint256 ratio;
    }

    struct TrancheVaultInitializeParams {
        address _currency;
        address _strategyManager;
        address _protocolRegistry;
        bytes _trancheVaultToken;
        address _accessController;
        address _feeModule;
        address _vaultManagerConfig;
    }

    struct StrategyWithdrawParams {
        uint256 underlyingAmount;
        uint256 strategyTokenAmount;
    }

    struct TrancheVaultDeployParams {
        address _currency;
        uint256 _vaultManagerFee;
        uint256 _vaultSlippage;
        uint256 _vaultSwapSlippage;
        uint256 _vaultLpSlippage;
        uint256 _userDepositLimit;
        uint256 _vaultTvlLimit;
        address _userTreasury;
        address _vaultTreasury;
        string _assetTokenName;
        string _assetTokenSymbol;
        string _juniorTokenName;
        string _juniorTokenSymbol;
        bool _whitelistedVault;
        StrategyInfo[] _strategies;
        address _dustStrategy;
        uint256 _vaultTid;
        uint256 _senior_block_fee_rate;
    }

    struct AccessControllerInitializeParams {
        address creatorAddress;
        address trancheVaultAddress;
        address strategyManagerAddress;
        address feeModuleAddress;
    }

    struct Claim {
        bytes32 identifier;
        address account;
        uint256 amount;
        bytes32[] merkleProof;
    }

    struct VaultManagerConfigInitializeParams {
        address _strategyManager;
        address _accessController;
        address _protocolRegistry;
        uint256 _vaultManagerFee;
        address _userTreasury;
        uint256 _userDepositLimit;
        uint256 _vaultTvlLimit;
        bool _whitelistedVault;
        uint256 _vaultSlippage;
        uint256 _vaultSwapSlippage;
        uint256 _vaultLpSlippage;
        uint256 _vaultTid;
    }
}

contracts/interfaces/core/IEventEmitter..content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

interface IEventEmitter {
    // Protocol Registry Event Functions
    function protocolPauseUpdatedEvent(bool newState) external;
    function wethUpdatedEvent(address oldWETH, address newWETH) external;
    function protocolFeeUpdatedEvent(uint256 oldFee, uint256 newFee) external;
    function protocolTreasuryUpdatedEvent(address oldTreasury, address newTreasury) external;
    function oracleUpdatedEvent(address oldOracle, address newOracle) external;
    function honeyFactoryUpdatedEvent(address oldFactory, address newFactory) external;
    function rewardDistributorUpdatedEvent(address oldManager, address newManager) external;
    function eventEmitterUpdatedEvent(address oldEmitter, address newEmitter) external;
    function strategyAddressesAddedEvent(address[] memory strategyAddresses) external;
    function redistributorAddressesAddedEvent(address[] memory redistributorAddresses) external;
    function rewardsClaimerUpdatedEvent(address oldClaimer, address newClaimer) external;
    function strategyPauseUpdatedEvent(address strategy, bool oldState, bool newState) external;

    function setWhitelistAddress(address[] memory contractAddresses) external;
    function removeWhitelistAddress(address[] memory contractAddresses) external;

    function depositedEvent(
        address trancheVault,
        address account,
        address token,
        uint256 amount,
        uint256 depositAmount,
        uint256 depositAmountAfterSlippage,
        uint256 mintAmount,
        uint256 tid,
        uint256 currentRate,
        uint256 timestamp
    ) external;
    function withdrawnEvent(
        address trancheVault,
        address account,
        address token,
        uint256 tid,
        uint256 amount,
        uint256 balanceWithdrawn,
        uint256 currentRate,
        uint256 timestamp
    ) external;
    function feeWithdrawnEvent(address trancheVault, uint256 amount, uint256 timestamp) external;
    function trancheAddedEvent(address trancheVault, uint256 tid) external;
    function trancheStartedEvent(address trancheVault, uint256 tid, uint256 cycle, uint256 principal) external;
    function trancheSettledEvent(
        address trancheVault,
        uint256 tid,
        uint256 cycle,
        uint256 principal,
        uint256 capital,
        uint256 rate
    ) external;

    function strategyDepositFailedEvent(address strategyContractAddress) external;
    function strategyWithdrawalFailedEvent(address strategyContractAddress) external;
    function strategyInternalFunctionFailedEvent(
        address strategyContractAddress,
        string calldata functionName
    ) external;
    function strategyDepositSuccessEvent(address strategyContractAddress, uint256 amount) external;
    function strategyWithdrawSuccessEvent(address strategyContractAddress, uint256 amount) external;
    function stakeBgtEvent(address strategy, uint256 amount) external;
    function withdrawBgtEvent(address strategy, uint256 amount) external;
    function claimBgtRewardEvent(address[] memory strategies, uint256[] memory amounts) external;
    function juniorTokenBalanceUpdated(address token, uint256 amount) external;
    function investmentUpdatedEvent(
        address trancheVault,
        uint256 seniorVaultInvestments,
        uint256 juniorVaultInvestments,
        uint256 totalActualSeniorVaultInvestments,
        uint256 totalActualJuniorVaultInvestments,
        uint256 totalActualSeniorVaultInvestmentsAfterSlippage,
        uint256 totalActualJuniorVaultInvestmentsAfterSlippage,
        uint256 currentStrategyBalance,
        uint256 totalInvestment,
        uint256 seniorTokenSupply,
        uint256 juniorTokenSupply
    ) external;
    function deployTrancheVaultEvent(
        uint256 index,
        address trancheVault,
        address strategyManager,
        address vaultManagerConfig,
        address feeModule,
        address accessController,
        // address rewardsDistributor,
        address seniorToken,
        address juniorToken
    ) external;
    function upgradeStrategyManagerEvent(address newStrategyManager) external;
    function upgradeTrancheVaultEvent(address newTrancheVault) external;
    function strategiesAndRatiosChangedEvent(address strategyManager, bool value) external;
    function ratioChangedEvent(
        address strategyManager,
        address strategyAddress,
        uint256 ratioBefore,
        uint256 ratioAfter
    ) external;
    function rewardsAddedEvent(
        address rewardsDistributor,
        address[] memory users,
        address token,
        uint256 totalAmount
    ) external;
    function claimRewardsEvent(address rewardsDistributor, address user, address token, uint256 amount) external;
    function whitelistUpdated(address account, bool status) external;
    function upgradeFeeModuleEvent(address newFeeModule) external;
    function upgradeVaultManagerConfigEvent(address newVaultManagerConfig) external;
    function rewardMetadataUpdatedEvent(address token, bytes32 merkleRoot, uint256 updatedAt) external;
    function rewardClaimedEvent(
        address[] calldata tokens,
        address[] calldata accounts,
        uint256[] calldata amounts
    ) external;
    function strategyRewardClaimedEvent(address strategy, address[] memory tokens, uint256[] memory amounts, uint256 compoundedAmount, uint256 receiptTokenAmount, uint256 dustAmount) external;

    function strategyStateSetEvent(address strategy, bool isStrategy) external;
    function bgtStakeGaugeSetEvent(
        address strategy,
        address gauge,
        address receiptToken,
        address redistributorAddress,
        uint256 amount
    ) external;
    function validatorInfoSetEvent(
        bytes[] memory publicKey,
        uint256[] memory boostingRatio,
        uint256[] memory unboostingRatio
    ) external;
    function unboostDelayAndRequestTimeoutSetEvent(uint256 unboostDelay, uint256 requestTimeout) external;
    function beraClaimedEvent(address user, uint256 amount) external;

    /**
     * @notice Emits a protocol fee charged event
     * @param trancheVault Address of the tranche vault
     * @param totalProfit Total profit amount
     * @param protocolFee Protocol fee amount
     * @param vaultManagerFee Vault manager fee amount
     * @param newHighWaterMark New high water mark value
     */
    function protocolFeeChargedEvent(
        address trancheVault,
        uint256 totalProfit,
        uint256 protocolFee,
        uint256 vaultManagerFee,
        uint256 newHighWaterMark
    ) external;

    /**
     * @notice Emits a fee minted event
     * @param trancheVault Address of the tranche vault
     * @param recipient Address receiving the minted fee
     * @param amount Amount of fee minted
     */
    function feeMintedEvent(address trancheVault, address recipient, uint256 amount) external;

    /**
     * @notice Emits a performance fee charged event
     * @param trancheVault Address of the tranche vault
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param profit Total profit amount
     * @param feeAmount Fee amount charged
     * @param newHwm New high water mark value
     */
    function performanceFeeChargedEvent(
        address trancheVault,
        uint256 trancheId,
        uint256 profit,
        uint256 feeAmount,
        uint256 newHwm
    ) external;

    /**
     * @notice Emits a fee parameters updated event
     * @param seniorEntryFee Senior tranche entry fee in basis points
     * @param juniorEntryFee Junior tranche entry fee in basis points
     * @param seniorExitFee Senior tranche exit fee in basis points
     * @param juniorExitFee Junior tranche exit fee in basis points
     * @param seniorExitFeePeriod Senior tranche exit fee period in seconds
     * @param juniorExitFeePeriod Junior tranche exit fee period in seconds
     * @param seniorPerformanceFee Senior tranche performance fee in basis points
     * @param juniorPerformanceFee Junior tranche performance fee in basis points
     */
    function feeParametersUpdatedEvent(
        uint256 seniorEntryFee,
        uint256 juniorEntryFee,
        uint256 seniorExitFee,
        uint256 juniorExitFee,
        uint256 seniorExitFeePeriod,
        uint256 juniorExitFeePeriod,
        uint256 seniorPerformanceFee,
        uint256 juniorPerformanceFee
    ) external;

    function feeParameterUpdatedEvent(bytes4 selector, uint256 oldValue, uint256 newValue) external;
    function vaultTreasuryUpdatedEvent(address oldTreasury, address newTreasury) external;
    function seniorRatePerBlockUpdatedEvent(uint256 oldRate, uint256 newRate) external;
    function entryFeeChargedEvent(
        address trancheVault,
        uint256 trancheId,
        uint256 grossAmount,
        uint256 feeAmount,
        uint256 netAmount
    ) external;
    function exitFeeChargedEvent(
        address trancheVault,
        address user,
        uint256 trancheId,
        uint256 grossAmount,
        uint256 feeAmount,
        uint256 netAmount
    ) external;
    function depositTimestampUpdatedEvent(
        address user,
        uint256 trancheId,
        uint256 oldTimestamp,
        uint256 newTimestamp
    ) external;
    function privilegedChangeScheduledEvent(bytes32 operation, uint256 readyAt) external;
    function privilegedChangeExecutedEvent(bytes32 operation) external;
    function privilegedChangeCancelledEvent(bytes32 operation) external;
    function privilegedChangeDelayUpdatedEvent(uint256 oldDelay, uint256 newDelay) external;


    /**
     * @notice Emits an added whitelisted user event
     * @param caller The address of the caller
     * @param users The array of whitelisted users
     */
    function addedWhitelistedUserEvent(address caller, address[] memory users) external;

    /**
     * @notice Emits a removed whitelisted user event
     * @param caller The address of the caller
     * @param users The array of whitelisted users
     */
    function removedWhitelistedUserEvent(address caller, address[] memory users) external;

    /**
     * @notice Emits a dust strategy changed event
     * @param strategyManager The address of the strategy manager
     * @param dustStrategy The address of the dust strategy
     */
    function dustStrategyChangedEvent(address strategyManager, address dustStrategy) external;

    /**
     * @notice Emits a strategy addresses removed event
     * @param strategyAddresses The array of strategy addresses
     */
    function strategyAddressesRemovedEvent(address[] memory strategyAddresses) external;
}

