contracts/interfaces/core/IStrategyManag.content:
//SPDX-License-Identifier: MIT
pragma solidity 0.8.30;
import {FunctionParameters} from "../../library/core/FunctionParameters.sol";

interface IStrategyManager {
    function token() external view returns (address);

    function deposit(uint256 _amount, uint256 _swapSlippage, uint256 _lpSlippage) external returns (uint256);

    function withdraw(
        uint256 _amount,
        uint256 _swapSlippage,
        uint256 _lpSlippage
    ) external returns (uint256 withdrawnAmount);

    function stakeForRewards(address account, uint amount) external;

    function unstakeForRewards(address account, uint amount) external;

    function claimAll(address account) external;

    function init(
        address _currency,
        address _protocolRegistry,
        address _accessController,
        FunctionParameters.StrategyInfo[] memory _strategies,
        address _dustStrategy
    ) external;

    function getIndividualAndAllStrategyBalance() external view returns (uint256[] memory, uint256);

    /// @notice Harvests every active strategy, then returns the post-harvest total balance.
    function harvestAndReport(uint256 _slippage, uint256 _lpSlippage) external returns (uint256);

    function setTokenAddresses(address _seniorToken, address _juniorToken) external;

    function getCurrentAssetVaultRate() external view returns (uint256);

    function getStrategyInformation() external view returns (address[] memory, uint256[] memory);

    /// @notice The vault's base/deposit token. Pending rewards are valued in it.
    function currency() external view returns (address);

    function dustStrategy() external view returns (address);
}

contracts/interfaces/core/IStrategy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {FunctionParameters} from "../../library/core/FunctionParameters.sol";
interface IStrategy {
    function deposit(uint256 _wantAmt, uint256 _slippage, uint256 _lpSlippage) external returns (uint256, uint256);

    function withdraw(
        FunctionParameters.StrategyWithdrawParams memory _params,
        uint256 _slippage,
        uint256 _lpSlippage
    ) external;

    /**
     * @notice Claims and compounds any pending rewards for this strategy.
     * @param _slippage Max slippage for reward swaps
     * @param _lpSlippage Max LP slippage, ignored by strategies with no LP leg
     * @dev Uniform across every strategy so the StrategyManager can harvest in a
     *      single loop without knowing each one's reward shape. A strategy with
     *      nothing to claim implements this as a no-op rather than reverting,
     *      because the caller runs inside _updateInvestment() and must not fail.
     */
    function harvest(uint256 _slippage, uint256 _lpSlippage) external;

    function getUnderlyingBalance() external view returns (uint256);

    function getTokenBalance() external view returns (uint256);
}

/**
 * @notice Permissionless deposit entry point implemented by strategies that can absorb
 *         auto-compounded dust forwarded from another strategy without the StrategyManager
 *         round-trip. Caller must hold the strategy's base/underlying token and have approved
 *         the strategy for `_amount`.
 */
interface IStrategyDustReceiver {
    function depositBase(uint256 _amount) external;
}

